import operator
import re
import sys
import threading

_CYCLE = "#CYCLE!"
_DIV0 = "#DIV/0!"
_TOKEN_RE = re.compile(r"\s*(?:(<>|<=|>=|[-+*/(),:<>=])|([A-Z]+\d*)|(\d+))")
_FUNCS = {"SUM", "MIN", "MAX", "IF"}
_CMP = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


class _Err(Exception):
    def __init__(self, value):
        super().__init__(value)
        self.value = value


def _tokenize(text):
    tokens = []
    pos = 0
    text = text.rstrip()
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if not m:
            raise ValueError("bad formula text: %r" % text)
        pos = m.end()
        op, name, num = m.groups()
        if op:
            tokens.append(("op", op))
        elif num:
            tokens.append(("num", int(num)))
        elif name in _FUNCS:
            tokens.append(("func", name))
        else:
            tokens.append(("cell", name))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.t = tokens
        self.i = 0

    def peek(self, k=0):
        j = self.i + k
        return self.t[j] if j < len(self.t) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ValueError("expected %r" % op)

    def parse(self):
        return self.expr()

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "cell":
            return ("ref", val)
        if kind == "op" and val == "(":
            node = self.expr()
            self.expect_op(")")
            return node
        if kind == "func":
            self.expect_op("(")
            if val == "IF":
                return self.if_call()
            args = [self.arg()]
            while self.peek() == ("op", ","):
                self.take()
                args.append(self.arg())
            self.expect_op(")")
            return ("func", val, args)
        raise ValueError("unexpected token")

    def arg(self):
        if self.peek()[0] == "cell" and self.peek(1) == ("op", ":"):
            first = self.take()[1]
            self.take()
            second = self.take()[1]
            return ("range", first, second)
        return self.expr()

    def if_call(self):
        left = self.expr()
        kind, op = self.take()
        if kind != "op" or op not in _CMP:
            raise ValueError("expected comparison operator")
        right = self.expr()
        self.expect_op(",")
        then = self.expr()
        self.expect_op(",")
        other = self.expr()
        self.expect_op(")")
        return ("if", op, left, right, then, other)


def _range_names(a, b):
    c1, r1 = ord(a[0]) - ord("A"), int(a[1:])
    c2, r2 = ord(b[0]) - ord("A"), int(b[1:])
    for r in range(min(r1, r2), max(r1, r2) + 1):
        for c in range(min(c1, c2), max(c1, c2) + 1):
            yield chr(ord("A") + c) + str(r)


def _div(a, b):
    q = abs(a) // abs(b)
    return -q if (a < 0) != (b < 0) else q


def _solve(cells):
    memo = {}
    active = set()

    def get(name):
        if name not in cells:
            return 0
        if name in memo:
            v = memo[name]
        elif name in active:
            raise _Err(_CYCLE)
        else:
            active.add(name)
            try:
                v = compute(cells[name])
            except _Err as e:
                v = e.value
            finally:
                active.discard(name)
            memo[name] = v
        if isinstance(v, str):
            raise _Err(v)
        return v

    def range_vals(a, b):
        out = []
        for name in _range_names(a, b):
            if name in cells:
                out.append(get(name))
        return out

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return get(node[1])
        if kind == "neg":
            return -ev(node[1])
        if kind == "bin":
            op = node[1]
            a = ev(node[2])
            b = ev(node[3])
            if op == "+":
                return a + b
            if op == "-":
                return a - b
            if op == "*":
                return a * b
            if b == 0:
                raise _Err(_DIV0)
            return _div(a, b)
        if kind == "func":
            name, args = node[1], node[2]
            vals = []
            for a in args:
                if a[0] == "range":
                    vals.extend(range_vals(a[1], a[2]))
                else:
                    vals.append(ev(a))
            if name == "SUM":
                return sum(vals)
            if not vals:
                return 0
            return min(vals) if name == "MIN" else max(vals)
        if kind == "if":
            _, op, left, right, then, other = node
            a = ev(left)
            b = ev(right)
            return ev(then) if _CMP[op](a, b) else ev(other)
        raise ValueError("unknown node")

    def compute(text):
        text = text.strip()
        if not text.startswith("="):
            return int(text)
        return ev(_Parser(_tokenize(text[1:])).parse())

    out = {}
    for name in cells:
        try:
            out[name] = get(name)
        except _Err as e:
            out[name] = e.value
    return out


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    box = {}

    def run():
        try:
            box["result"] = _solve(cells)
        except BaseException as exc:
            box["error"] = exc

    old_limit = sys.getrecursionlimit()
    old_stack = threading.stack_size()
    sys.setrecursionlimit(1_000_000)
    threading.stack_size(256 * 1024 * 1024)
    try:
        t = threading.Thread(target=run)
        t.start()
        t.join()
    finally:
        sys.setrecursionlimit(old_limit)
        threading.stack_size(old_stack)

    if "error" in box:
        raise box["error"]
    return box["result"]
